        if (t >= this.nextY) { const q = r(); s.ty = q < 0.35 ? 0 : (r() < 0.5 ? -1 : 1) * (q < 0.6 ? 5 + r() * 35 : q < 0.7 ? 40 + r() * 40 : 80 + r() * 20); this.nextY = t + 5 + r() * 35; }
