      while (this.typed < this.o.type.length && t >= this.o.type[this.typed].t) {
        const c = this.o.type[this.typed++], term = sim.devs.find(d => d.kind === 'terminal' && (!c.terminal || d.it.id === String(c.terminal)));
        if (term) term.type(c.text);
      }
